internal static partial class CheckCandidateArenaLifecycle {
    static void FreshBpInspect(){
        var p=FreshLoadSaved(true,true,true,true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);
        var list=new System.Collections.Generic.List<GameState>();foreach(int slot in new[]{1,2,3,0}){uint uid=Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_contributors WHERE slot=@slot","slot",slot));list.Add(FreshContributor(uid,Convert.ToString(Sql("SELECT name FROM revora_fresh_contributors WHERE slot=@slot","slot",slot))));}list.Add(p);var players=list.ToArray();Server.GamePool=players;Call(typeof(Revora.Database.JiangHu),"LoadClient",p);Require(players.All(w=>!w.Fake && w.Account.State==AccountTable.AccountState.Player && !PirateFenced(w)) && p.Entity.Class==25);

        Require(FreshRelicSnapshot(p,players)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_relic_probe WHERE done")));
        foreach(var who in players)System.Console.WriteLine("[fresh-bp] uid="+who.Entity.UID+" class="+who.Entity.Class+" level="+who.Entity.Level+" reborn="+who.Entity.Reborn+" power="+who.Entity.BattlePower+" bag="+who.Inventory.Count+" equipped="+Sql("SELECT coalesce(string_agg(id::text||':'||position::text||':+'||plus::text,',' ORDER BY position),'none') FROM items WHERE entityid=@uid AND position BETWEEN 1 AND 20 AND warehouse=0","uid",(long)who.Entity.UID));
        System.Console.WriteLine("[career-process] career-fresh-bp-inspect-passed");System.Console.Out.Flush();Environment.Exit(0);
    }
    static string FreshBpInterruptedSnapshot(GameState p,GameState[] players){return Convert.ToString(Sql("SELECT json_build_object('prior',@prior::json,'wars',(SELECT row_to_json(r) FROM revora_pk_wars r WHERE run='pk-20-20410804-0'),'entries',(SELECT json_agg(r ORDER BY uid) FROM revora_pk_entries r WHERE run='pk-20-20410804-0'),'admissions',(SELECT json_agg(r ORDER BY uid) FROM revora_bp_admissions r WHERE run='pk-20-20410804-0'),'claims',(SELECT json_agg(r ORDER BY uid) FROM revora_bp_claims r WHERE run='pk-20-20410804-0'),'tokens',(SELECT json_agg(r ORDER BY item_uid) FROM revora_bp_tokens r WHERE uid=@uid))::text","prior",FreshRelicSnapshot(p,players),"uid",(long)p.Entity.UID));}
    static string FreshBpSnapshot(GameState p,GameState[] players){return Convert.ToString(Sql("SELECT json_build_object('interrupted',@prior::json,'war',(SELECT row_to_json(r) FROM revora_pk_wars r WHERE run='pk-20-20410811-0'),'entries',(SELECT json_agg(r ORDER BY uid) FROM revora_pk_entries r WHERE run='pk-20-20410811-0'),'admissions',(SELECT json_agg(r ORDER BY uid) FROM revora_bp_admissions r WHERE run='pk-20-20410811-0'),'claims',(SELECT json_agg(r ORDER BY uid) FROM revora_bp_claims r WHERE run='pk-20-20410811-0'))::text","prior",FreshBpInterruptedSnapshot(p,players)));}
    static void FreshBpSave(GameState p,GameState[] players,int stage){foreach(var who in players)Require(EntityTable.SaveEntity(who));Sql("UPDATE revora_fresh_bp_probe SET stage=@stage,snapshot=@snapshot","stage",stage,"snapshot",FreshBpSnapshot(p,players));}
    static void FreshBpJourney(string phase){
        var p=FreshLoadSaved(true,true,true,true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);
        var list=new System.Collections.Generic.List<GameState>();foreach(int slot in new[]{1,2,3,0}){uint uid=Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_contributors WHERE slot=@slot","slot",slot));list.Add(FreshContributor(uid,Convert.ToString(Sql("SELECT name FROM revora_fresh_contributors WHERE slot=@slot","slot",slot))));}list.Add(p);var players=list.ToArray();Server.GamePool=players;Call(typeof(Revora.Database.JiangHu),"LoadClient",p);Require(players.All(w=>!w.Fake && w.Account.State==AccountTable.AccountState.Player && !PirateFenced(w)) && p.Entity.Class==25);


        var peer=players[3];const string run="pk-20-20410811-0";var type=Feature("LocalPkWar");var current=type.GetField("Current",Hidden).GetValue(null);var instance=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;DateTime start=new DateTime(2041,8,12,3,0,0,DateTimeKind.Utc),now=start;Action<double> tick=minutes=>{now=start.AddMinutes(minutes);type.GetMethod("Tick",instance).Invoke(current,null);};
        if(phase=="career-fresh-bp-claim-recover"){
            Func<string,string> hash=value=>{using(var sha=System.Security.Cryptography.SHA256.Create())return System.BitConverter.ToString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(value))).Replace("-","").ToLowerInvariant();};
            Require((int)Sql("SELECT stage FROM revora_fresh_bp_probe")==2 && hash(Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_bp_probe")))=="c6626b2c81081ba048867de2392b52f5de5efc75bee6ff6f3cfb9e664a61414e" && hash(FreshBpSnapshot(p,players))=="818bbce7f093cc08a47ad32d43b6cf0996818171578f1de235b0d9ff5373ea86");
            Sql("UPDATE revora_fresh_bp_probe SET snapshot=@snapshot","snapshot",FreshBpSnapshot(p,players));System.Console.WriteLine("[career-process] "+phase+"-passed reviewed loser NPC approach only");Environment.Exit(0);return;
        }
        if(phase.EndsWith("recover")){
            Func<string,string> hash=value=>{using(var sha=System.Security.Cryptography.SHA256.Create())return System.BitConverter.ToString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(value))).Replace("-","").ToLowerInvariant();};
            Require((int)Sql("SELECT stage FROM revora_fresh_bp_probe")==0 && hash(Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_bp_probe")))=="74c322cb07efa1d99f9507ecc9a7ca530a3c881fac77af67a52971f0c0d8992f" && hash(FreshBpInterruptedSnapshot(p,players))=="57b078f66509c12d7ebf57955b8cfedaa8f732812a48bee1a58f6beafe271564");
            Require((long)Sql("SELECT count(*) FROM revora_bp_admissions WHERE run='pk-20-20410804-0'")==0 && (long)Sql("SELECT count(*) FROM revora_pk_wars WHERE run=@run","run",run)==0);Sql("UPDATE revora_fresh_bp_probe SET snapshot=@snapshot","snapshot",FreshBpSnapshot(p,players));System.Console.WriteLine("[career-process] "+phase+"-passed empty cancelled round preserved");Environment.Exit(0);return;
        }
        if(phase.EndsWith("state")){System.IO.File.WriteAllText("fresh-bp-before.json",Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_bp_probe")));System.IO.File.WriteAllText("fresh-bp-current.json",FreshBpSnapshot(p,players));System.Console.WriteLine("[career-process] "+phase+"-passed");Environment.Exit(0);return;}
        if(phase.EndsWith("prepare")){
            Require((bool)Sql("SELECT to_regclass('revora_fresh_bp_probe') IS NULL") && FreshRelicSnapshot(p,players)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_relic_probe WHERE done")) && !p.Entity.Dead && !peer.Entity.Dead && peer.Entity.BattlePower>=250 && peer.Entity.BattlePower<=300 && p.Inventory.Count<=30);
            var gear=new System.Collections.Generic.List<long>();var slots=new System.Collections.Generic.List<int>();int initial=p.Entity.BattlePower;
            foreach(byte slot in new byte[]{1,2,3,8,6,19,18}){if(p.Entity.BattlePower<=300)break;var item=p.Equipment.TryGetItem(slot);Require(item!=null);gear.Add(item.UID);slots.Add(slot);RetainedUpgradeUsage(p,0,slot,ItemUsage.Mode.UnequipItem);Require(p.Inventory.ContainsUID(item.UID) && p.Equipment.TryGetItem(slot)==null);}
            Require(p.Entity.BattlePower>=250 && p.Entity.BattlePower<=300);Sql("CREATE TABLE revora_fresh_bp_probe(stage int,gear bigint[],slots int[],initial_power int,items bigint[],snapshot text);INSERT INTO revora_fresh_bp_probe VALUES(0,@gear,@slots,@initial,ARRAY[]::bigint[],NULL)","gear",gear.ToArray(),"slots",slots.ToArray(),"initial",initial);FreshBpSave(p,players,0);System.Console.WriteLine("[fresh-bp] power="+initial+" -> "+p.Entity.BattlePower+" peer="+peer.Entity.BattlePower+" unequipped="+gear.Count);
        }else{
            Require(FreshBpSnapshot(p,players)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_bp_probe")));int stage=(int)Sql("SELECT stage FROM revora_fresh_bp_probe");
            if(phase.EndsWith("earn")){
                Require(stage==0 && p.Entity.BattlePower>=250 && p.Entity.BattlePower<=300 && peer.Entity.BattlePower>=250 && peer.Entity.BattlePower<=300);type.GetField("clock",instance).SetValue(current,(Func<DateTime>)(()=>now));tick(0);FreshClassicTalk(p,1002,91050,1);FreshClassicTalk(peer,1002,91050,1);Require(p.Map.BaseID==1730 && p.Entity.MapID==peer.Entity.MapID);tick(10);ushort arena=p.Entity.MapID;p.Attackable=peer.Attackable=true;p.CantAttack=peer.CantAttack=Time32.Now.AddSeconds(-1);int hits=0;
                while(!peer.Entity.Dead && hits<300 && p.Entity.MapID==arena){p.Entity.X=peer.Entity.X;p.Entity.Y=(ushort)(peer.Entity.Y+1);p.Screen.Add(peer.Entity);peer.Screen.Add(p.Entity);p.Entity.AttackStamp=Time32.Now.AddSeconds(-2);Revora.Network.GamePackets.Attack.HandleAttack(new Attack(true){Attacker=p.Entity.UID,Attacked=peer.Entity.UID,X=peer.Entity.X,Y=peer.Entity.Y,AttackType=Attack.Melee},p);hits++;}tick(10.02);
                Require((long)Sql("SELECT count(*) FROM revora_pk_wars WHERE run=@run AND state='complete' AND winner=@uid AND bp_valuable_reward","run",run,"uid",(long)p.Entity.UID)==1 && (long)Sql("SELECT count(*) FROM revora_pk_entries WHERE run=@run AND competitive AND admitted_at IS NOT NULL","run",run)==2 && (long)Sql("SELECT count(*) FROM revora_bp_claims WHERE run=@run","run",run)==0 && p.Entity.MapID==1002 && peer.Entity.MapID==1002);
                if(peer.Entity.Dead){peer.Entity.DeathStamp=Time32.Now.AddSeconds(-20);GeneralData.Revive(new Data(true){UID=peer.Entity.UID,ID=Data.Revive},peer);}Require(!peer.Entity.Dead);FreshBpSave(p,players,1);System.Console.WriteLine("[fresh-bp] calculated-hits="+hits);
            }else{
                type.GetField("clock",instance).SetValue(current,(Func<DateTime>)(()=>now));now=start.AddMinutes(11);
                if(phase.EndsWith("claim")){Require(stage==1);uint cp=p.Entity.ConquerPoints,chi=p.ChiPoints;var old=p.Inventory.Objects.Select(i=>i.UID).ToArray();HeartTalk(p,91050,10);var added=p.Inventory.Objects.Where(i=>!old.Contains(i.UID)).ToArray();Require(added.Length==2 && added.All(i=>i.Bound) && added.Count(i=>i.ID==3006840)==1 && added.Count(i=>ConquerItemInformation.BaseInformations[i.ID].PurificationLevel==7)==1 && p.Entity.ConquerPoints==cp+300 && p.ChiPoints==chi+5000);Sql("UPDATE revora_fresh_bp_probe SET items=@items","items",added.Select(i=>(long)i.UID).ToArray());HeartTalk(peer,91050,0);FreshBpSave(p,players,2);}
                else if(phase.EndsWith("restore")){Require(stage==2);var gear=(long[])Sql("SELECT gear FROM revora_fresh_bp_probe");var slots=(int[])Sql("SELECT slots FROM revora_fresh_bp_probe");for(int n=0;n<gear.Length;n++){RetainedUpgradeUsage(p,(uint)gear[n],(uint)slots[n],ItemUsage.Mode.EquipItem);Require(p.Equipment.TryGetItem((byte)slots[n]).UID==gear[n]);}Require(p.Entity.BattlePower==(int)Sql("SELECT initial_power FROM revora_fresh_bp_probe"));FreshBpSave(p,players,3);}
                else Require(phase.EndsWith("reload") && stage==3 && p.Entity.BattlePower==(int)Sql("SELECT initial_power FROM revora_fresh_bp_probe"));
                var rewards=(long[])Sql("SELECT items FROM revora_fresh_bp_probe");Require(rewards.Length==2 && rewards.All(id=>p.Inventory.ContainsUID((uint)id)));string saved=FreshBpSnapshot(p,players);foreach(var who in new[]{p,peer}){HeartTalk(who,91050,10);HeartTalk(who,91050,10);}Require(saved==FreshBpSnapshot(p,players));
            }
            Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=11114 AND source='bp-pk-v1' AND source_key=@run","uid",(long)p.Entity.UID,"run",run)==1);
        }
        Require(FreshBpSnapshot(p,players)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_bp_probe")));System.Console.WriteLine("[career-process] "+phase+"-passed");System.Console.Out.Flush();System.Environment.Exit(0);
    }
}
